{"content": "import wasmtime as w

def compile_ok(name, wat):
    try:
        raw = bytearray(w.wat2wasm(wat))
        print(f"OK   {name}: {len(raw)} bytes")
        return raw
    except Exception as e:
        print(f"FAIL {name}: {str(e).splitlines()[0]}")
        return None

import_block = (
    '(import "agpack/emit.text" "emit.text" (func $emit (param i32 i32) (result i32)))'
    '(import "agpack/clock.now" "clock.now" (func $clk (result i32)))'
)

def add():
    return (
        "(module"
        '(memory (export "mem") 1 16)'
        import_block
        '(func (export "add") (param i32) (param i32) (result i32)'
        '  (i32.add (local.get 0) (local.get 1))'
        ')'
    )

def call_imports():
    return (
        "(module"
        '(memory (export "mem") 1 16)'
        import_block
        '(func (export "run") (param i32) (param i32) (result i32 i32)'
        '  (drop (call $clk))'
        '  (drop (call $emit (local.get 0) (local.get 1)))'
        '  (local.get 0) (local.get 1)'
        ')'
    )

compile_ok("bare-add", add())
compile_ok("call-imports", call_imports())
